import{d as c,C as t,o as u,c as b,j as a,a as o,E as r,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第六十八章","description":"依士卒之帅、不与争与为之下的王注，读四个善与不争成用的关系。","frontmatter":{"title":"道德经第六十八章","description":"依士卒之帅、不与争与为之下的王注，读四个善与不争成用的关系。","category":"guide","aliases":["道德经第六十八章","老子第六十八章","dao de jing chapter 68"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-68.md","filePath":"daoism/dao-de-jing/chapter-68.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-68.md"},w=c({...m,setup(g){const i=[{id:"command-without-bullying",label:"善为士者不武",showLabel:!0,sentences:[["善为",{text:"士",glossary:"shi"},"者不",{text:"武",glossary:"wu"},"，"]],note:["【白话】善于做统兵之帅的人，不崇尚以武力抢先凌迫别人。这里说的是如何运用力量，而不是有没有承担军事事务的能力。","【王弼注择要】「士，卒之帅也。武，尚先陵人也。」士与武都依本句的军事语境解释，陵保留所据录文字样。","【读法】与第十五章善为士者相参时，要区分本章士卒之帅与彼章修养行道之人的语境，不能因字相同就套同一义项。"]},{id:"respond-without-anger",label:"善战者不怒",showLabel:!0,sentences:[["善战者不怒，"]],note:["【白话】善于作战的人，不以愤怒推动行动。他的应对不以争着先发、先挑起冲突为能事，而能有所回应。","【王弼注择要】「后而不先，应而不唱，故不在怒。」唱在这里与倡相通，指先倡、先发。","【读法】不怒不是否认人会有情绪，而是不让怒气成为行动准则；后而不先也须与前文不敢为天下先连读。"]},{id:"prevail-without-contesting",label:"善胜敌者不与",showLabel:!0,sentences:[["善胜敌者",{text:"不与",glossary:"buyu"},"，"]],note:["【白话】善于胜过敌手的人，不与对方争强斗胜。句意把胜敌的能力与争强的姿态分开，不以争得更激烈为善胜。","【王弼注择要】「不与争也。」本页据此将不与读作不与敌争强，不按不给予解释。","【读法】经文没有在这里展开一套具体战法。读者可留意不争如何与前面的不武、不怒相通，不从短句自行推出任何局面都必能取胜。"]},{id:"serve-those-you-work-with",label:"善用人者为之下",showLabel:!0,sentences:[["善用人者为之",{text:"下",glossary:"xia"},"。"]],note:["【白话】善于任用、与人共事的人，愿意在对方面前自处谦下。用人不是只要求别人出力，也涉及自己怎样对待他们。","【读法】所据此句后未见独立逐句王注，可与下文用人而不为之下的注释合读，理解谦下与得人之力的关系。","【读法】这里仍是古代用人语境。现代协作相参时，要进一步看参与者是否得到尊重、条件与表达空间，不能只学会一套使人出力的姿态。"]},{id:"virtue-and-shared-strength",label:"是谓不争之德",showLabel:!0,sentences:[["是谓",{text:"不争",glossary:"buzheng"},"之德，是谓用人之力，"]],note:["【白话】这些做法，就叫作不争的德，也叫作善于发挥他人力量的本领。前面四句由此收束为不争与成用的关系。","【王弼注择要】「用人而不为之下，则力不为用也。」注说明若始终自居其上、不能谦下，便难得到人的力量。","【读法】用人之力不只在于自己掌握了多少资源，也在于他人的能力能否在关系中真正发挥；本章因此不能只读成压住情绪的个人修养。"]},{id:"accord-with-heaven",label:"是谓配天古之极",showLabel:!0,sentences:[["是谓",{text:"配天",glossary:"peitian"},"古之极。"]],note:["【白话】这就叫作与天道相配，是古来所推重的最高准则。末句把前面的不争与成用，提升到与天相合的尺度。","【读法】配天取与天道相合，古之极取古来最高准则；所据此句未见单独逐句王注，不以另章注语补成原注。","【读法】结尾保留古代以天道论人事的表达。现代读者可从少凌迫、善应对、能协作观察实际成效，不把配天当作个人权威的认证。"]}],n=[{id:"shi",term:"士",sense:2},{id:"wu",term:"武",sense:1},{id:"buyu",term:"不与",sense:1},{id:"xia",term:"下",sense:1},{id:"buzheng",term:"不争",sense:1},{id:"peitian",term:"配天",sense:1}];return(x,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第六十八章",tabindex:"-1"},[o("道德经第六十八章 "),a("a",{class:"header-anchor",href:"#道德经第六十八章","aria-label":'Permalink to "道德经第六十八章"'},"​")],-1)),r(s,{title:"善于任事的人，为什么不逞武、不动怒",summary:"四个善分别说统兵、作战、胜敌和用人，四个回应却是少逞武、不怒、不与争、为之下。本章以这些克制解释不争之德与用人之力：减少凌迫、争强与自居其上，才给应对和协力留下余地。",points:[{label:"先读",text:"四个善依次展开，不武、不怒、不与、为之下各有所指。"},{label:"再辨",text:"士在所据王注中是士卒之帅；武侧重尚先凌人，不只指有没有力量。"},{label:"后看",text:"末三句由不争的德转到用人的力，最后以配天古之极提高到原则层面。"}],hint:"士读 shì，武读 wǔ，不与本页读 bù yǔ，取不与敌争强之意；配天读 pèi tiān。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:i,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"善为士者不武，善战者不怒，善胜敌者不与。",tone:"三种克制",guide:"不逞武、不以怒出、不与争强，共同说明善不只在外显的强势。"},{text:"善用人者为之下。",tone:"把自己放回关系中",guide:"能否得人之力，与是否愿意谦下相连。"},{text:"是谓不争之德，是谓用人之力，是谓配天古之极。",tone:"由行事到原则",guide:"德、力与配天逐层收束，既有克制，也有实际成用。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-四个善是在否定统兵与行动吗" tabindex="-1">象：四个善是在否定统兵与行动吗？ <a class="header-anchor" href="#象-四个善是在否定统兵与行动吗" aria-label="Permalink to &quot;象：四个善是在否定统兵与行动吗？&quot;">​</a></h3><p>它们都以善为前提，仍讨论统兵、作战、胜敌与用人。经文所收束的是行动方式：不凌迫、不以怒气争先、不与敌争强、愿意谦下。</p><h3 id="理-为什么用人之力与为之下相连" tabindex="-1">理：为什么用人之力与为之下相连？ <a class="header-anchor" href="#理-为什么用人之力与为之下相连" aria-label="Permalink to &quot;理：为什么用人之力与为之下相连？&quot;">​</a></h3><p>王注指出不为之下则力不为用。人的力量能否发挥，与关系中的位置和待遇有关；始终自居其上而只要求别人贡献，恰可能使能力无法成用。</p><h3 id="用-今天如何把不怒落到协作里" tabindex="-1">用：今天如何把不怒落到协作里？ <a class="header-anchor" href="#用-今天如何把不怒落到协作里" aria-label="Permalink to &quot;用：今天如何把不怒落到协作里？&quot;">​</a></h3><p>遇到分歧时，先明确事实、目标与各方需要承担的部分，再决定行动。怒气可以被看见，但不必直接成为指令；谦下也应落实到能听取反馈和修正安排。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>区分需要解决的事与需要赢过的人。</strong> 发生争执时，先说清当前要解决什么、哪些事实尚待确认。让回应围绕问题展开，可以减少为了压过对方而不断加码。</p><p><strong>让能力发挥有实际条件。</strong> 需要他人承担工作时，一并给出信息、时间和调整余地；听取其专业判断，承认其贡献。为之下可以从承担这些协作责任开始。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是否把语气更强、反应更快当作善于任事？在一次协作里，我能怎样调整自己的位置，使别人的判断和能力真正发挥？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文、标点与别名沿本站保留，据卷四 006b 电子录文核对；四善与末三句依语义拆为六段。</li><li>士依士卒之帅也，武依尚先陵人也，不与依不与争也释读。与第十五章士的行道语境分义，不把不武解释为没有军事能力。</li><li>所据注作应而不唱，唱按先倡理解，节引保留唱字；陵不静默改成凌后引用。</li><li>为之下据后文用人而不为之下的注释参读；配天古之极未见单独逐句王注。古注节引转简体并加标点，尚未逐字核对影印。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_004.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷四 HFL 本电子录文，006b</a>。</p>',15))])}}});export{_ as __pageData,w as default};
